$availableSections = []; foreach ($availableItems as $item) { $sid = trim((string) ($item['section_id'] ?? '')); if ($sid !== '') $availableSections[$sid] = ['section_id' => $sid, 'title' => (string) ($item['section_title'] ?? 'Section')]; }
if ($template && empty($template['items'])) $template['items'] = [['item_id' => '', 'assignment_id' => '', 'is_required' => 1, 'teacher_note' => '', 'estimated_duration' => null, 'weight' => null, 'locked_until_previous' => 0, 'section_title' => '', 'item_type' => '', 'template_type' => '', 'coverage' => []]];
