.template-admin{max-width:1280px;margin-top:55px;padding:24px}.template-grid{display:grid;grid-template-columns:320px minmax(0,1fr);gap:16px}.template-card{padding:18px;margin-bottom:16px;border:1px solid var(--border);border-radius:var(--radius-lg);background:var(--surface);box-shadow:var(--shadow-sm)}.template-list{display:grid;gap:7px;margin:14px 0 0}.template-list a{display:block;padding:10px;border:1px solid var(--border);border-radius:var(--radius-md);color:var(--text-primary);text-decoration:none}.template-list a.is-selected{border-color:var(--primary);background:color-mix(in srgb,var(--primary) 8%,var(--surface))}.template-list small{display:block;color:var(--text-muted);margin-top:3px}.template-toolbar,.template-actions{display:flex;gap:9px;align-items:end;flex-wrap:wrap}.template-rows{display:grid;gap:10px}.template-row{display:grid;grid-template-columns:28px minmax(180px,1fr) 110px 100px 38px;gap:8px;align-items:start;padding:12px;border:1px solid var(--border);border-radius:var(--radius-md);background:var(--surface-elevated)}.template-row textarea,.template-row-options{grid-column:2/-1}.template-row-options{display:flex;gap:14px;flex-wrap:wrap;color:var(--text-secondary);font-size:.78rem}.template-row-actions{display:flex;flex-direction:column;gap:4px}.template-row-actions button{padding:3px 7px;border:1px solid var(--border);border-radius:var(--radius-sm);background:var(--surface);color:var(--text-muted)}.template-coverage{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:8px}.template-coverage label{font-size:.75rem;color:var(--text-muted)}.template-help{color:var(--text-muted);font-size:.84rem;line-height:1.5}@media(max-width:900px){.template-grid{grid-template-columns:1fr}}@media(max-width:640px){.template-admin{padding:14px}.template-row{grid-template-columns:26px minmax(0,1fr) 38px}.template-row:nth-child(n)>:nth-child(3),.template-row:nth-child(n)>:nth-child(4),.template-row-options,.template-row textarea,.template-coverage{grid-column:2}.template-row-actions{grid-column:3;grid-row:1}}
</style></head><body class="dash ds-bg-primary"><div class="col-12 d-flex"><?php include 'layouts/admin/aside.php'; ?><div class="main-content in-active"><?php include 'layouts/admin/top-nav.php'; ?><main class="template-admin"><section class="template-card"><div class="template-toolbar"><div><p class="course-manager-eyebrow">Student support</p><h1 class="h3 mb-1">Recovery Plan Templates</h1><p class="template-help mb-0">Build reusable plans from real published course items. Templates never hold student progress.</p></div><form method="get" action="<?= $escape($base . '/admin/recovery-plan-templates') ?>"><label>Course<select class="form-control" name="course_id" onchange="this.form.submit()"><?php foreach ($courses as $course): ?><option value="<?= $escape($course['course_id']) ?>" <?= $courseId === (string) $course['course_id'] ? 'selected' : '' ?>><?= $escape($course['course_title']) ?></option><?php endforeach; ?></select></label></form></div></section><?php if (is_array($flash)): ?><div class="alert alert-<?= !empty($flash['ok']) ? 'success' : 'danger' ?>"><?= $escape($flash['message'] ?? '') ?></div><?php endif; ?><div class="template-grid"><aside><section class="template-card"><div class="template-actions"><h2 class="h5 mb-0">Templates</h2><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan-template/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="action" value="create"><input type="hidden" name="course_id" value="<?= $escape($courseId) ?>"><button class="btn btn-primary btn-sm">New template</button></form></div><div class="template-list"><?php foreach ($templates as $candidate): ?><a class="<?= $templateId === (int) $candidate['id'] ? 'is-selected' : '' ?>" href="<?= $escape($base . '/admin/recovery-plan-templates?course_id=' . rawurlencode($courseId) . '&template_id=' . (int) $candidate['id']) ?>"><strong><?= $escape($candidate['title']) ?></strong><small><?= (int) ($candidate['assigned_count'] ?? 0) ?> assigned · <?= $escape(ucfirst($candidate['status'])) ?></small></a><?php endforeach; ?><?php if (!$templates): ?><p class="template-help">No templates for this course yet.</p><?php endif; ?></div></section></aside><section><?php if (!$template): ?><section class="template-card"><p class="template-help mb-0">Create a template to start selecting course items.</p></section><?php else: ?><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan-template/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="template_id" value="<?= (int) $template['id'] ?>"><section class="template-card"><div class="template-actions"><div class="flex-grow-1"><input class="form-control mb-2" name="title" value="<?= $escape($template['title']) ?>" maxlength="180"><textarea class="form-control" name="description" maxlength="1000" placeholder="Template description (optional)"><?= $escape($template['description'] ?? '') ?></textarea></div><button class="btn btn-primary" type="submit">Save template</button></div><p class="template-help mt-3 mb-0">Editing applies to future assignments by default. Choose a wider update scope only when you intend to update existing student plans.</p><div class="template-rows mt-3" id="template-rows"><?php foreach (($template['items'] ?? []) as $index => $item): $coverageItems = array_values(array_filter($item['coverage'] ?? [], static fn(array $row): bool => ($row['covered_item_id'] ?? '') !== '')); $coverageSections = array_values(array_filter($item['coverage'] ?? [], static fn(array $row): bool => ($row['covered_section_id'] ?? '') !== '')); $coverageTypes = array_map(static fn(array $row): string => (string) ($row['coverage_type'] ?? ''), $item['coverage'] ?? []); $topics = array_values(array_filter(array_map(static fn(array $row): string => (string) ($row['topic_label'] ?? ''), $item['coverage'] ?? []))); ?><div class="template-row" data-template-row><span class="template-row-index" data-index><?= $index + 1 ?></span><select class="form-control form-control-sm" name="items[<?= $index ?>][item_id]"><?php foreach ($availableItems as $available): ?><option value="<?= $escape($available['item_id']) ?>" <?= (string) $available['item_id'] === (string) $item['item_id'] ? 'selected' : '' ?>><?= $escape($available['item_title']) ?> · <?= $escape(mmh_recovery_plan_item_label($available)) ?></option><?php endforeach; ?></select><input class="form-control form-control-sm" type="number" name="items[<?= $index ?>][estimated_duration]" min="0" max="1440" value="<?= $item['estimated_duration'] === null ? '' : (int) $item['estimated_duration'] ?>" placeholder="Minutes"><input class="form-control form-control-sm" type="number" name="items[<?= $index ?>][weight]" min="0" step="0.01" value="<?= $item['weight'] === null ? '' : $escape($item['weight']) ?>" placeholder="Weight"><div class="template-row-options"><label><input type="hidden" name="items[<?= $index ?>][required]" value="0"><input type="checkbox" name="items[<?= $index ?>][required]" value="1" <?= !empty($item['is_required']) ? 'checked' : '' ?>> Required</label><label><input type="hidden" name="items[<?= $index ?>][locked_until_previous]" value="0"><input type="checkbox" name="items[<?= $index ?>][locked_until_previous]" value="1" <?= !empty($item['locked_until_previous']) ? 'checked' : '' ?>> Lock until previous complete</label><span><?= $escape($item['section_title'] ?: 'General') ?> · <?= $escape(mmh_recovery_plan_item_label($item)) ?></span></div><textarea class="form-control form-control-sm" name="items[<?= $index ?>][teacher_note]" maxlength="1000" placeholder="Teacher note (optional)"><?= $escape($item['teacher_note'] ?? '') ?></textarea><div class="template-coverage"><label>Covered items<select class="form-control form-control-sm" name="coverage[<?= $index ?>][items][]" multiple size="3"><?php foreach ($availableItems as $available): ?><option value="<?= $escape($available['item_id']) ?>" <?= in_array((string) $available['item_id'], array_map(static fn(array $row): string => (string) $row['covered_item_id'], $coverageItems), true) ? 'selected' : '' ?>><?= $escape($available['item_title']) ?></option><?php endforeach; ?></select></label><label>Covered sections<select class="form-control form-control-sm" name="coverage[<?= $index ?>][sections][]" multiple size="3"><?php foreach ($availableSections as $availableSection): ?><option value="<?= $escape($availableSection['section_id']) ?>" <?= in_array((string) $availableSection['section_id'], array_map(static fn(array $row): string => (string) $row['covered_section_id'], $coverageSections), true) ? 'selected' : '' ?>><?= $escape($availableSection['title']) ?></option><?php endforeach; ?></select></label><label>Coverage topic<input class="form-control form-control-sm" name="coverage[<?= $index ?>][topic]" value="<?= $escape(implode(', ', $topics)) ?>" maxlength="255"></label></div><div class="template-row-actions"><button type="button" data-move="up">↑</button><button type="button" data-move="down">↓</button><button type="button" data-remove-row>×</button></div></div><?php endforeach; ?></div><div class="template-actions mt-3"><select id="template-picker" class="form-control form-control-sm"><option value="">Add existing course item</option><?php foreach ($availableItems as $available): ?><option value="<?= $escape($available['item_id']) ?>"><?= $escape($available['item_title']) ?></option><?php endforeach; ?></select><button class="btn btn-outline-secondary btn-sm" type="button" id="template-add">Add item</button></div><div class="template-actions mt-3"><label>When assigned students exist<select class="form-control" name="apply_mode"><option value="future">Apply only to future assignments</option><option value="not_started">Apply to students who have not started</option><option value="all">Apply to all assigned students</option></select></label></div></section></form><div class="template-actions mb-3"><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan-template/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="action" value="duplicate"><input type="hidden" name="template_id" value="<?= (int) $template['id'] ?>"><button class="btn btn-outline-secondary btn-sm">Duplicate template</button></form><?php if (($template['status'] ?? '') !== 'archived'): ?><form method="post" action="<?= $escape($base . '/admin/requests/recovery-plan-template/save') ?>"><input type="hidden" name="_token" value="<?= $escape(mmh_auth_csrf_token()) ?>"><input type="hidden" name="action" value="archive"><input type="hidden" name="template_id" value="<?= (int) $template['id'] ?>"><button class="btn btn-outline-danger btn-sm">Archive template</button></form><?php endif; ?><a class="btn btn-primary btn-sm" href="<?= $escape($base . '/admin/recovery-plan-assignments?template_id=' . (int) $template['id']) ?>">Assign to students</a></div><?php endif; ?></section></div></main></div></div><template id="template-row-template"><div></div></template><script>
document.addEventListener('click',function(event){var button=event.target.closest('[data-move],[data-remove-row]');if(!button)return;var row=button.closest('[data-template-row]');if(!row)return;if(button.hasAttribute('data-remove-row'))row.remove();else{var target=button.getAttribute('data-move')==='up'?row.previousElementSibling:row.nextElementSibling;if(target)button.getAttribute('data-move')==='up'?row.parentNode.insertBefore(row,target):row.parentNode.insertBefore(target,row);}renumber();});
function renumber(){document.querySelectorAll('[data-template-row]').forEach(function(r,i){r.querySelector('[data-index]').textContent=i+1;r.querySelectorAll('[name]').forEach(function(input){input.name=input.name.replace(/^(items|coverage)\[\d+\]/,function(_,group){return group+'['+i+']';});});});}
document.getElementById('template-add')?.addEventListener('click',function(){var picker=document.getElementById('template-picker'),list=document.getElementById('template-rows');if(!picker||!list||!picker.value)return;var source=list.querySelector('[data-template-row]');if(!source)return;var row=source.cloneNode(true);row.querySelectorAll('input,textarea').forEach(function(input){if(input.type==='hidden')input.value='0';else if(input.type==='checkbox')input.checked=input.name.indexOf('[required]')>=0;else input.value='';});row.querySelectorAll('select').forEach(function(select){Array.from(select.options).forEach(function(option){option.selected=select.multiple?false:option.value===picker.value;});});var itemSelect=row.querySelector('select[name*="items["]');if(itemSelect)itemSelect.value=picker.value;list.appendChild(row);picker.value='';renumber();});
renumber();
</script></body></html>
